import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.zip.ZipFile;

public class ShipMain {
    private static final Path OUT = Paths.get("/app/jarhearth/watch.json");
    private static final Path MARK = Paths.get("/app/opslip/MARK.txt");

    public static int rib_n(String[] a) throws Exception {
        // A failed watch must never leave an earlier success ledger behind.
        Files.deleteIfExists(OUT);
        if (a.length != 1 || !lid_q()) {
            return 1;
        }

        Path bag = Paths.get(a[0]);
        int word = Integer.parseInt(Files.readAllLines(bag).get(0).trim());
        // Zero denotes a gatherer which never publishes.
        if (word == 0) {
            return 1;
        }

        Tarn board = new Tarn();
        int seen = Glue.haul(board, word);
        if (seen == 0) {
            return 1;
        }

        String name = bag.getFileName().toString();
        String note = Files.readString(MARK).trim();
        String body = "{\"seen\":" + seen + ",\"bag\":\"" + json(name)
                + "\",\"note\":\"" + json(note) + "\"}\n";
        Files.createDirectories(OUT.getParent());
        Files.write(OUT, body.getBytes(StandardCharsets.UTF_8));
        return 0;
    }

    public static void main(String[] a) throws Exception {
        System.exit(rib_n(a));
    }

    static boolean lid_q() {
        try {
            String want = Files.readString(MARK).trim();
            try (ZipFile z = new ZipFile("/app/jarhearth/ship.jar")) {
                var e = z.getEntry("STAMP");
                if (e == null) {
                    return false;
                }
                String got = new String(z.getInputStream(e).readAllBytes(), StandardCharsets.UTF_8).trim();
                return want.equals(got);
            }
        } catch (Exception ex) {
            return false;
        }
    }

    private static String json(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
